sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float cutoff;
uniform float softness;
uniform float mode;
uniform float amount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 sstep3(float e0, float e1, float3 x) {
    return float3(smoothstep(e0, e1, x.x), smoothstep(e0, e1, x.y), smoothstep(e0, e1, x.z));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float3 inv = 1.0 - s;
    float3 k = sstep3(cutoff - softness, cutoff + softness + 0.0001, s);
    float3 o = mix(s, inv, k);
    if (mode > 0.5 && mode < 1.5) {
        float kl = smoothstep(cutoff - softness, cutoff + softness + 0.0001, luma(s));
        o = mix(s, inv, kl);
    } else if (mode > 1.5) {
        float3 m = mode < 2.5 ? float3(1.0, 0.0, 0.0) : (mode < 3.5 ? float3(0.0, 1.0, 0.0) : float3(0.0, 0.0, 1.0));
        o = mix(s, o, m);
    }
    o = mix(s, o, amount);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
